actions.script:
avatarInitial = (contactName ?: '?').trim().take(1).toUpperCase()
isOrg = (organization != null)
isDisabled = (party?.disabled == 'Y')
poCount = poList ? poList.size() : 0
billCount = payableInvoiceList ? payableInvoiceList.size() : 0
// truthful PO status breakdown for the Purchase Orders metric card (spec: "N completed / M tentative"),
// derived live from the same poList the Orders tab uses — never hard-coded.
poCompleted = 0; poTentative = 0
if (poList) poList.each { _po ->
    def _si = ec.entity.find("moqui.basic.StatusItem").condition("statusId", _po.statusId).useCache(true).one()
    def _d = _si?.description ?: (_po.statusId ?: '')
    if (_d ==~ /(?i).*(complet|approv|finaliz).*/) poCompleted++ else poTentative++
}
rolesDisplay = []
roleChipList = []
def _seenR = [] as Set
// only the roles the Add-Role picker manages are removable from here; internal/owner roles show but can't be stripped
def _removable = ['Customer', 'Supplier'] as Set
partyRoles.each { r ->
    def rt = ec.entity.find("mantle.party.RoleType").condition("roleTypeId", r.roleTypeId).useCache(true).one()
    def nm = rt?.description ?: r.roleTypeId
    if (!_seenR.contains(nm)) {
        _seenR.add(nm)
        rolesDisplay << nm
        roleChipList << [roleTypeId: r.roleTypeId, name: nm, removable: _removable.contains(r.roleTypeId)]
    }
}
// Orders&Bills tab is role-focused: vendors see Purchase Orders + Vendor Bills, customers see
// Invoices + Sales Orders + Quotations. A section still shows whenever it actually has data, so
// no real transaction history is ever hidden (a contact with both roles sees both groups).
isVendorRole = partyRoles.any { it.roleTypeId == 'Supplier' }
isCustomerRole = partyRoles.any { it.roleTypeId == 'Customer' }
priceListName = party?.priceListId
try {
    if (party?.priceListId) {
        def pl = ec.entity.find("zenith.erp.pricing.PriceList").condition("priceListId", party.priceListId).useCache(true).one()
        if (pl != null) priceListName = pl.priceListName ?: pl.name ?: party.priceListId
    }
} catch (Throwable _t) { }
